package com.example.spring_blog.user.apiLogin;import com.example.spring_blog.user.UserResponse;import lombok.extern.slf4j.Slf4j;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.util.LinkedMultiValueMap;import org.springframework.util.MultiValueMap;import org.springframework.web.client.RestTemplate;//카카오 서버와 http 통신만 담당하는 클래스@Component@Slf4jpublic class KakaoApiClient {    //    application.yaml의 변수를 가져올 때 사용    @Value("${oauth.kakao.client-id}")    private String kakaoClientId;    @Value("${oauth.kakao.client-secret}")    private String kakaoClientSecret;    @Value("${oauth.kakao.redirect-uri}")    private String redirectUri;    //    인가요청 주소    private static String AUTHORIZE_URL = "https://kauth.kakao.com/oauth/authorize";    //    엑세스 토큰 요청 주소    private static String TOKEN_URL = "https://kauth.kakao.com/oauth/token";    //    프로필 이미지 주소    private static String PROFILE_URL = "https://kapi.kakao.com/v2/user/me";    //    한 번 만들면 여러 요청에서 함께 써도 안전하게 설계되어 하나만 만들어 재사용함.    private final RestTemplate restTemplate = new RestTemplate();    //    1. 카카오 로그인 화면 주소    public String getAuthorizeUrl() {        return AUTHORIZE_URL                + "?client_id=" + kakaoClientId                + "&redirect_uri=" + redirectUri                + "&response_type=code";    }    public UserResponse.KaKaoOauthToken requestAccessToken(String code) {        //            1. 받은 인가코드를 활용해서 토큰 요청(POST)        HttpHeaders headers = new HttpHeaders();        headers.setContentType(MediaType.APPLICATION_FORM_URLENCODED); // <- application/x-www-form-urlencoded;charset=utf-8        MultiValueMap<String, String> params = new LinkedMultiValueMap<>();        params.add("grant_type", "authorization_code");        params.add("client_id", kakaoClientId);        params.add("redirect_uri", redirectUri);        params.add("code", code);//           클라이언트 시크릿 활설화시 반드시 포함되어야함.        params.add("client_secret", kakaoClientSecret);//            body + header        HttpEntity<MultiValueMap<String, String>> tokenRequest = new HttpEntity(params, headers);        ResponseEntity<UserResponse.KaKaoOauthToken> response = restTemplate.exchange(                TOKEN_URL,                HttpMethod.POST,                tokenRequest,                UserResponse.KaKaoOauthToken.class        );        log.info("토큰발급완료"); // 값은 남기지 않음.        return response.getBody();    }    public UserResponse.KakaoUserInfo requestProfile(String accessToken) {        HttpHeaders headers = new HttpHeaders();        headers.setBearerAuth(accessToken);        HttpEntity request = new HttpEntity(headers);        ResponseEntity<UserResponse.KakaoUserInfo> response = restTemplate.exchange(                PROFILE_URL,                HttpMethod.GET,                request,                UserResponse.KakaoUserInfo.class        );        return response.getBody();    }}